// Guitar Grit / Warmth: Suno Studio audio effect for the GUITAR stem (applied to rendered audio, not a lyric tag).
// Serves clean fingerpicked acoustic (low grit) through distorted / overdriven guitar (high grit).
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Warmth tilt EQ: lowshelf +tilt near 300Hz and highshelf -tilt near 4kHz (opposite via g.mul by -1),
//      driven by one 'warmth tilt' param.
//   3. Grit: scale by 'grit' (dB via g.dbToLin) then g.tanh saturation; low grit stays clean, high overdrives.
//   4. Presence: g.biquad peaking near 3kHz driven by 'presence' dB for bite.
//   5. Tone: g.biquad lowpass at 'tone' to roll off fizz.
//   6. Dry/wet: g.lerp between trimmed dry and processed by 'dry/wet mix'.
//   7. Output gain, bypass select via g.lerp, then g.tanh safety before g.output.
// Bypass: g.lerp(bypass, out, trimmed) ASSUMES the 'bypass' enum resolves to 0 ('off') / 1 ('on'), so
// 'off' passes the PROCESSED signal and 'on' passes the DRY signal (see AUTHORING.md).
// ASSUMPTION: the shelf/peaking g.biquad stages pass a 'gainDb' field not confirmed from the one example (see AUTHORING.md).
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var tiltDb = g.input('warmth tilt');
  var gritDb = g.input('grit');
  var presenceDb = g.input('presence');
  var tone = g.input('tone');
  var mixPct = g.input('dry/wet mix');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var gritLin = g.dbToLin(gritDb);
  var mix = g.clamp(g.div(mixPct, g.constant(100)), g.zero(), g.constant(1));
  var negTilt = g.mul(tiltDb, g.constant(-1));

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var low = g.biquad({ input: trimmed, cutoff: g.constant(300), resonance: g.constant(0.707), mode: 'lowshelf', gainDb: tiltDb });
    var tilted = g.biquad({ input: low, cutoff: g.constant(4000), resonance: g.constant(0.707), mode: 'highshelf', gainDb: negTilt });
    var gritted = g.tanh(g.mul(tilted, gritLin));
    var pres = g.biquad({ input: gritted, cutoff: g.constant(3000), resonance: g.constant(0.9), mode: 'peaking', gainDb: presenceDb });
    var toned = g.biquad({ input: pres, cutoff: tone, resonance: g.constant(0.707), mode: 'lowpass' });
    var wet = g.lerp(mix, trimmed, toned);
    var out = g.mul(wet, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
